// Heurística de Nielsen 1: 50 problemas aprofundados pela UBERTRIZ
window.PROBLEMAS.push(
{"id":1,"h":1,"sev":3,"t":"Botão sem retorno ao clicar","sym":"No portal da prefeitura, a pessoa clica em “Enviar requerimento”, nada muda na tela e ela clica de novo — o pedido é registrado duas vezes.","ten":"O processamento precisa acontecer nos bastidores, mas quem usa precisa saber que ele está acontecendo.","sol":"Mudar o botão na hora para “Enviando…”, desabilitá-lo durante o processamento e mostrar confirmação clara ao concluir.","c":"C32","u":"U19","e":"micro","i":"I09","m":"Envios duplicados por sessão","freq":3,"imp":2,"pers":2,"pf":"P01","hx":["BS1.4","SH3","DN2","TG10","LX6","ISO2","WC4.1"],"dom":"publico","vul":"idosos","ag":"Ganha: quem envia e a equipe que conferia duplicados. Perde: ninguém; o custo é de desenvolvimento.","alt":"E se o problema não for falta de retorno, e sim lentidão do servidor? Então o retorno apenas disfarça a causa.","esc":{"micro":"Mudar o botão na hora para “Enviando…”, desabilitá-lo durante o processamento e mostrar confirmação clara ao concluir.","meso":"Estado único do envio (rascunho → enviando → recebido) em todo o fluxo, com número de protocolo na confirmação.","macro":"Servidor idempotente: o mesmo requerimento enviado duas vezes vira um só."},"st":"add","sub":"Em vez de avisar, remover o risco: aceitar cliques repetidos sem efeito (idempotência), sem a pessoa precisar esperar.","ops":["U23","U01"],"c2":{"c":"C09","t":"Com o botão desabilitado, uma falha de rede deixa a pessoa presa, sem poder reenviar.","mit":"Reabilitar com “Tentar de novo” após um tempo limite e dizer o que houve."},"cf":"Sem intervenção, os requerimentos duplicados continuam gerando retrabalho e filas de conferência.","lim":{"l":"L03","t":"Depende de o servidor responder em poucos segundos; em rede lenta, “Enviando…” dura demais."},"ide":{"mais":["I09","I04"],"menos":["I03"]},"ref":"Estaria errada se os duplicados vierem de recarregar a página ou de robôs, e não de cliques repetidos.","conf":"alta"},
{"id":2,"h":1,"sev":3,"t":"Upload longo sem progresso","sym":"No ambiente virtual, o TCC de 200 MB carrega por minutos sem indicação alguma; a estudante acha que travou e fecha a aba.","ten":"O envio é inevitavelmente longo, mas a espera precisa parecer controlada.","sol":"Barra de progresso com percentual e tempo estimado; permitir continuar navegando enquanto o envio segue em segundo plano.","c":"C15","u":"U09","e":"micro","i":"I09","m":"Taxa de abandono durante uploads","freq":2,"imp":2,"pers":2,"pf":"P02","hx":["BS1.4","SH3","DN2","TG10","MB8","ISO5","LX6"],"dom":"educacao","vul":"conexão ruim","ag":"Ganha: estudantes com internet instável. Perde: a plataforma arca com mais armazenamento temporário.","alt":"E se o problema for o tamanho do arquivo exigido, e não a espera? Talvez o PDF não precise ter 200 MB.","esc":{"micro":"Barra de progresso com percentual e tempo estimado; permitir continuar navegando enquanto o envio segue em segundo plano.","meso":"Envio em partes retomáveis: se a conexão cair, continua de onde parou.","macro":"Aceitar entrega por link de nuvem institucional em vez de upload direto."},"st":"add","sub":"Reduzir o que é enviado: comprimir o PDF no navegador antes do envio.","ops":["U31","U01"],"c2":{"c":"C16","t":"Enviar em segundo plano ocupa a banda que a pessoa usa para continuar navegando.","mit":"Priorizar a navegação e mostrar que o envio desacelera quando necessário."},"cf":"Sem intervenção, estudantes perdem prazos de entrega por quedas de conexão no fim do upload.","lim":{"l":"L08","t":"Em redes móveis instáveis, nem o envio em partes garante conclusão rápida."},"ide":{"mais":["I09","I07"],"menos":["I03"]},"ref":"Estaria errada se o abandono vier de o prazo acabar, e não da falta de progresso.","conf":"alta"},
{"id":3,"h":1,"sev":2,"t":"Tela em branco durante o carregamento","sym":"No posto de saúde, o prontuário fica em branco por 3 segundos antes de aparecer qualquer coisa.","ten":"Os dados demoram a chegar, mas a página precisa responder imediatamente.","sol":"Mostrar primeiro a estrutura (skeleton screen) e preencher os dados conforme chegam — a estrutura e o conteúdo aparecem em tempos diferentes.","c":"C04","u":"U08","e":"micro","i":"I09","m":"Tempo até a primeira resposta visual","freq":3,"imp":1,"pers":2,"pf":"P02","hx":["BS1.4","TG10","LX6","DN1","MB8","ISO7"],"dom":"saude","vul":"conexão ruim","ag":"Ganha: profissionais que atendem em unidades com rede lenta. Perde: o skeleton sugere que os dados vão chegar; se falharem, a tela parece travada para sempre.","alt":"E se o problema for carregar dados demais de uma vez? Então a solução é carregar menos, não disfarçar a espera.","esc":{"micro":"Mostrar primeiro a estrutura (skeleton screen) e preencher os dados conforme chegam — a estrutura e o conteúdo aparecem em tempos diferentes.","meso":"Carregar primeiro o que o atendimento usa (alergias, medicação) e o histórico completo sob demanda.","macro":"Cache local do prontuário dos pacientes agendados no dia."},"st":"add","sub":"Tirar da tela inicial os blocos pesados que quase ninguém consulta.","ops":["U31","U20"],"c2":{"c":"C27","t":"O skeleton sugere que os dados vão chegar; se falharem, a tela parece travada para sempre.","mit":"Tempo limite com mensagem e opção de recarregar só o bloco."},"cf":"Sem intervenção, a espera em branco é lida como sistema caído e a consulta começa sem o prontuário.","lim":{"l":"L08","t":"Em unidades de saúde com internet muito ruim, nem o carregamento progressivo resolve."},"ide":{"mais":["I09","I02"],"menos":["I03"]},"ref":"Estaria errada se a demora vier do servidor e não da rede local.","conf":"alta"},
{"id":4,"h":1,"sev":2,"t":"Salvamento automático invisível","sym":"O texto é salvo sozinho, mas ninguém sabe; as pessoas copiam tudo para outro lugar “por garantia”.","ten":"O salvamento deve ser automático e silencioso, mas também confiável aos olhos de quem escreve.","sol":"Indicador discreto junto ao título: “Salvando…” → “Salvo às 14:32”.","c":"C34","u":"U01","e":"micro","i":"I04","m":"Cópias manuais e salvamentos redundantes","freq":3,"imp":1,"pers":2,"pf":"P01","hx":["BS1.4","SH3","DN2","TG13","ISO2","GP2"],"dom":"trabalho","vul":"","ag":"Ganha: quem escreve, que deixa de copiar texto por insegurança. Perde: nada.","alt":"E se a desconfiança vier de perdas passadas? Então o indicador não basta; é preciso histórico de versões.","esc":{"micro":"Indicador discreto junto ao título: “Salvando…” → “Salvo às 14:32”.","meso":"Histórico de versões acessível no mesmo lugar do indicador.","macro":"Política de retenção de versões comunicada no produto."},"st":"add","sub":"Remover o botão “Salvar” que ainda existe e confunde, já que tudo é automático.","ops":["U36","U19"],"c2":{"c":"C17","t":"Um indicador piscando a cada tecla vira distração.","mit":"Atualizar o indicador só ao concluir, de forma discreta."},"cf":"Sem intervenção, as pessoas continuam mantendo cópias paralelas e versões divergentes.","lim":{"l":"L03","t":"Exige salvamento confiável; se ele falhar às vezes, o indicador mente."},"ide":{"mais":["I04","I09"],"menos":[]},"ref":"Estaria errada se as cópias forem feitas por hábito de backup, e não por dúvida sobre o salvamento.","conf":"alta"},
{"id":5,"h":1,"sev":3,"t":"Etapas sem indicação de posição","sym":"No pedido de benefício online, a pessoa não sabe quantas telas faltam e desiste no meio.","ten":"O processo precisa ser dividido em etapas, mas deve parecer curto e previsível.","sol":"Indicador de etapas com nomes (“2 de 4 · Entrega”) sempre visível no topo.","c":"C34","u":"U31","e":"meso","i":"I09","m":"Abandono por etapa do checkout","freq":3,"imp":2,"pers":2,"pf":"P02","hx":["BS1.1","SH4","DN1","LX12","LX11","ISO2","TG16"],"dom":"publico","vul":"baixa escolaridade","ag":"Ganha: quem pede benefícios pela primeira vez. Perde: mostrar muitas etapas pode desanimar logo no começo.","alt":"E se o problema forem etapas demais, e não a falta de indicação? Então mostrar “1 de 9” pode desanimar.","esc":{"micro":"Nome curto e claro em cada etapa.","meso":"Indicador de etapas com nomes (“2 de 4 · Entrega”) sempre visível no topo.","macro":"Reduzir as etapas usando dados que o governo já tem."},"st":"add","sub":"Eliminar etapas cujos dados já estão em bases oficiais.","ops":["U12","U01"],"c2":{"c":"C20","t":"Mostrar muitas etapas pode desanimar logo no começo.","mit":"Agrupar em 3 ou 4 blocos e mostrar o tempo estimado total."},"cf":"Sem intervenção, a desistência no meio do pedido de benefício continua alta.","lim":{"l":"L06","t":"Reduzir etapas depende de acordos entre órgãos para compartilhar dados."},"ide":{"mais":["I09","I07"],"menos":["I03"]},"ref":"Estaria errada se a desistência vier da falta de documentos em mãos, e não da desorientação.","conf":"alta"},
{"id":6,"h":1,"sev":3,"t":"Status de pedido opaco","sym":"O pedido mostra “Em processamento” por quatro dias; a pessoa liga para o suporte.","ten":"A logística tem muitas etapas internas, mas o cliente só precisa das que importam para ele.","sol":"Linha do tempo com eventos reais (pago, separado, enviado, em rota), previsão de entrega e aviso a cada mudança.","c":"C33","u":"U12","e":"macro","i":"I09","m":"Chamados “onde está meu pedido?”","freq":3,"imp":2,"pers":2,"pf":"P08","hx":["BS1.4","SH3","SH4","GP3","ISO2","MB1"],"dom":"comercio","vul":"","ag":"Ganha: o cliente e a central de atendimento. Perde: a logística precisa expor eventos que eram internos.","alt":"E se o problema for o prazo real ser longo? Então transparência sem previsão confiável só expõe o atraso.","esc":{"micro":"Etiqueta de status traduzida em linguagem comum.","meso":"Linha do tempo com eventos e previsão de entrega na página do pedido.","macro":"Linha do tempo com eventos reais (pago, separado, enviado, em rota), previsão de entrega e aviso a cada mudança."},"st":"add","sub":"Remover estados internos que não significam nada para o cliente (“Em processamento”).","ops":["U19","U04"],"c2":{"c":"C26","t":"Mostrar cada evento expõe atrasos que antes ficavam escondidos.","mit":"Assumir o atraso com nova previsão e compensação quando houver."},"cf":"Sem intervenção, o suporte continua respondendo “onde está meu pedido?” como principal motivo de contato.","lim":{"l":"L06","t":"Depende de a transportadora enviar eventos confiáveis."},"ide":{"mais":["I09","I04"],"menos":["I02"]},"ref":"Estaria errada se os contatos vierem de atrasos reais, e não da falta de informação.","conf":"alta"},
{"id":7,"h":1,"sev":4,"t":"Conexão perdida sem aviso","sym":"O app do agente comunitário continua aceitando visitas sem internet, mas elas falham em silêncio — o registro some.","ten":"O app precisa funcionar em rede instável, mas não pode fingir que tudo foi salvo.","sol":"Aviso claro de “sem conexão”, fila local das ações e sincronização automática ao reconectar, com confirmação.","c":"C30","u":"U22","e":"meso","i":"I04","m":"Ações perdidas por falha de rede","freq":2,"imp":3,"pers":2,"pf":"P14","hx":["MB8","MB1","TG13","ISO6","BS1.4","SH3"],"dom":"saude","vul":"zona rural","ag":"Ganha: agentes de saúde em áreas sem sinal. Perde: a equipe de TI, que passa a tratar conflitos de sincronização.","alt":"E se o app nem devesse depender de rede? Então o problema é de arquitetura, não de aviso.","esc":{"micro":"Aviso “sem conexão — salvando no aparelho”.","meso":"Aviso claro de “sem conexão”, fila local das ações e sincronização automática ao reconectar, com confirmação.","macro":"Arquitetura local-first para todo o trabalho de campo."},"st":"add","sub":"Tirar do fluxo de campo as etapas que exigem rede (consultas online desnecessárias).","ops":["U21","U01"],"c2":{"c":"C35","t":"Registros feitos offline podem conflitar com alterações feitas no servidor.","mit":"Mostrar os conflitos na sincronização e deixar a pessoa decidir."},"cf":"Sem intervenção, visitas registradas em zona rural se perdem e o indicador de cobertura fica errado.","lim":{"l":"L04","t":"Exige armazenamento suficiente no aparelho e bateria para sincronizar depois."},"ide":{"mais":["I04","I08"],"menos":["I03"]},"ref":"Estaria errada se as perdas vierem de aparelhos sem memória, e não da falta de conexão.","conf":"alta"},
{"id":8,"h":1,"sev":3,"t":"Filtros ativos esquecidos","sym":"A lista aparece vazia e a pessoa acha que não há dados — havia um filtro aplicado na semana passada.","ten":"O filtro deve persistir para economizar trabalho, mas não pode esconder informação sem avisar.","sol":"Chips com os filtros ativos acima dos resultados, cada um removível, e botão “Limpar tudo”.","c":"C24","u":"U01","e":"micro","i":"I09","m":"Buscas repetidas sem resultado","freq":2,"imp":2,"pers":2,"pf":"P01","hx":["BS1.4","DN1","GP2","TG15","ISO2","SH8"],"dom":"comercio","vul":"","ag":"Ganha: quem compra. Perde: quem queria manter os filtros perde a preferência.","alt":"E se o problema for os filtros persistirem entre sessões sem necessidade?","esc":{"micro":"Chips com os filtros ativos acima dos resultados, cada um removível, e botão “Limpar tudo”.","meso":"Filtros persistem só durante a sessão; ao voltar dias depois, a lista começa limpa.","macro":"Política de persistência consistente em todas as listas do produto."},"st":"add","sub":"Não persistir filtros entre sessões, a menos que a pessoa os salve.","ops":["U21","U24"],"c2":{"c":"C21","t":"Quem queria manter os filtros perde a preferência.","mit":"Oferecer “Salvar esta busca”."},"cf":"Sem intervenção, a pessoa conclui que o produto não existe e vai à concorrência.","lim":{"l":"L07","t":"Chips demais em telas pequenas ocupam espaço."},"ide":{"mais":["I09"],"menos":["I03"]},"ref":"Estaria errada se as listas vazias vierem de estoque zerado, e não de filtros esquecidos.","conf":"alta"},
{"id":9,"h":1,"sev":3,"t":"Não se sabe onde se está","sym":"No ambiente virtual de aprendizagem, o menu não destaca a seção atual; estudantes se perdem entre telas parecidas.","ten":"A navegação precisa ser discreta, mas também orientar.","sol":"Destacar o item atual (cor, peso, marcador) e mostrar trilha de navegação (breadcrumb).","c":"C10","u":"U01","e":"micro","i":"I09","m":"Cliques em “voltar” por sessão","freq":3,"imp":1,"pers":3,"pf":"P01","hx":["DN1","TG16","BS1.1","WC2.4","ISO2","GP6"],"dom":"educacao","vul":"","ag":"Ganha: estudantes e professores. Perde: nada.","alt":"E se o problema for a estrutura de menus confusa, e não a falta de destaque?","esc":{"micro":"Destacar o item atual (cor, peso, marcador) e mostrar trilha de navegação (breadcrumb).","meso":"Trilha de navegação e títulos de página que repetem o item do menu.","macro":"Revisar a arquitetura de informação do ambiente virtual com card sorting."},"st":"add","sub":"Reduzir a quantidade de seções parecidas, fundindo as que têm a mesma função.","ops":["U10","U04"],"c2":{"c":"C17","t":"Destaques fortes competem com o conteúdo.","mit":"Destaque discreto, mas com mais de um sinal (cor + marcador)."},"cf":"Sem intervenção, estudantes se perdem entre “Materiais”, “Recursos” e “Conteúdos”.","lim":{"l":"L07","t":"A estrutura depende de como cada professor organiza a disciplina."},"ide":{"mais":["I09"],"menos":[]},"ref":"Estaria errada se as pessoas souberem onde estão, mas não souberem para onde ir.","conf":"alta"},
{"id":10,"h":1,"sev":3,"t":"Processo em lote sem relatório","sym":"A importação de 5.000 contatos diz “Iniciada” e nada mais; ninguém sabe o que falhou.","ten":"O lote roda depois e sozinho, mas o resultado precisa voltar para quem o iniciou.","sol":"Relatório ao final (importados, com erro, ignorados), notificação quando terminar e link direto para corrigir as falhas.","c":"C13","u":"U19","e":"meso","i":"I09","m":"Registros com erro não corrigidos","freq":2,"imp":2,"pers":3,"pf":"P04","hx":["SH3","SH4","GP3","BS5.3","ISO6","TG15"],"dom":"trabalho","vul":"","ag":"Ganha: quem importa dados e o time de dados. Perde: um relatório longo exige tempo para corrigir cada falha.","alt":"E se o problema for a qualidade da planilha de origem? Então o relatório mostra o sintoma, não a causa.","esc":{"micro":"Contador de sucesso e falha na notificação.","meso":"Relatório ao final (importados, com erro, ignorados), notificação quando terminar e link direto para corrigir as falhas.","macro":"Validação da planilha no momento do upload, antes do lote."},"st":"add","sub":"Eliminar a necessidade do lote: sincronizar contatos diretamente com a fonte.","ops":["U25","U12"],"c2":{"c":"C31","t":"Um relatório longo exige tempo para corrigir cada falha.","mit":"Agrupar os erros por tipo e oferecer correção em massa."},"cf":"Sem intervenção, registros com erro ficam para trás sem que ninguém saiba.","lim":{"l":"L03","t":"Depende de o processamento registrar o motivo de cada falha."},"ide":{"mais":["I09","I04"],"menos":["I03"]},"ref":"Estaria errada se ninguém consultar o relatório; então o problema seria de notificação.","conf":"alta"},
{"id":11,"h":1,"sev":2,"t":"Notificações lidas e não lidas iguais","sym":"Todas as notificações têm a mesma aparência; a pessoa não sabe o que é novo.","ten":"A lista guarda o histórico, mas precisa destacar o que ainda não foi visto.","sol":"Diferenciar não lidas (ponto, fundo, negrito), mostrar contador e permitir “marcar todas como lidas”.","c":"C17","u":"U11","e":"micro","i":"I09","m":"Notificações novas ignoradas","freq":3,"imp":1,"pers":2,"pf":"P01","hx":["DN1","BS1.3","GP9","TG3","MB5","LX9"],"dom":"comunicacao","vul":"neurodivergentes","ag":"Ganha: quem se sobrecarrega com notificações. Perde: produtos que dependem de engajamento por alerta.","alt":"E se o problema for o excesso de notificações, e não a falta de distinção entre lidas e não lidas?","esc":{"micro":"Diferenciar não lidas (ponto, fundo, negrito), mostrar contador e permitir “marcar todas como lidas”.","meso":"Agrupar notificações por tipo e resumir as de baixa prioridade.","macro":"Resumo diário opcional em vez de alertas contínuos."},"st":"add","sub":"Cortar as notificações que não pedem ação.","ops":["U35","U01"],"c2":{"c":"C26","t":"Reduzir notificações diminui métricas de engajamento que o negócio acompanha.","mit":"Medir ações concluídas, não aberturas."},"cf":"Sem intervenção, notificações importantes se perdem no volume e a pessoa desliga todas.","lim":{"l":"L06","t":"Metas de engajamento internas podem resistir à redução."},"ide":{"mais":["I09","I03"],"menos":[]},"ref":"Estaria errada se as pessoas lerem tudo de qualquer forma; então não há ganho.","conf":"média"},
{"id":12,"h":1,"sev":2,"t":"Carrinho sem contador","sym":"O ícone do carrinho não mostra quantos itens há; a pessoa abre só para conferir.","ten":"O ícone deve ser discreto, mas informar o estado da compra.","sol":"Contador numérico no ícone e animação curta ao adicionar um item.","c":"C34","u":"U01","e":"micro","i":"I09","m":"Aberturas do carrinho só para conferir","freq":3,"imp":1,"pers":2,"pf":"P01","hx":["DN1","BS1.4","SH3","LX4","TG15"],"dom":"comercio","vul":"","ag":"Ganha: quem compra. Perde: um pouco de simplicidade: mais um elemento animado no topo.","alt":"E se o problema for a pessoa não confiar que o item foi adicionado? Então falta confirmação, não contador.","esc":{"micro":"Contador numérico no ícone e animação curta ao adicionar um item.","meso":"Mini-resumo do carrinho ao adicionar, com opção de continuar comprando.","macro":"Carrinho persistente e sincronizado entre dispositivos."},"st":"add","sub":"Remover a página intermediária “Item adicionado”, que interrompe a navegação.","ops":["U19","U12"],"c2":{"c":"C17","t":"Animações a cada item adicionado incomodam em compras grandes.","mit":"Animação sutil e só na primeira adição."},"cf":"Sem intervenção, as pessoas abrem o carrinho repetidamente só para conferir.","lim":{"l":"L03","t":"Nenhum limite relevante."},"ide":{"mais":["I09"],"menos":["I03"]},"ref":"Estaria errada se as visitas ao carrinho forem para rever preços, e não quantidades.","conf":"alta"},
{"id":13,"h":1,"sev":3,"t":"Formulário enviado sem confirmação","sym":"Após pedir o agendamento do exame, a página volta ao início sem mensagem; pacientes pedem de novo por dúvida.","ten":"O envio termina nos bastidores, mas quem enviou precisa de um fechamento.","sol":"Tela ou mensagem de confirmação com resumo do que foi enviado e próximo passo esperado.","c":"C04","u":"U19","e":"micro","i":"I04","m":"Reenvios por dúvida","freq":3,"imp":2,"pers":2,"pf":"P01","hx":["SH4","BS1.4","DN2","ISO2","LX8","GP2"],"dom":"saude","vul":"idosos","ag":"Ganha: pacientes e a recepção, que recebe menos ligações. Perde: uma tela de confirmação longa demais esconde a informação principal.","alt":"E se o problema for a pessoa não saber o que fazer depois (jejum, documentos)?","esc":{"micro":"Tela ou mensagem de confirmação com resumo do que foi enviado e próximo passo esperado.","meso":"Confirmação por SMS ou e-mail com data, local e preparo do exame.","macro":"Integração com a agenda do laboratório para confirmar em tempo real."},"st":"add","sub":"Remover campos que depois são pedidos de novo na recepção.","ops":["U20","U22"],"c2":{"c":"C17","t":"Uma tela de confirmação longa demais esconde a informação principal.","mit":"Destacar data, hora e local; o resto em lista curta."},"cf":"Sem intervenção, pacientes reenviam o pedido ou ligam para confirmar.","lim":{"l":"L03","t":"Depende de o envio de SMS estar integrado."},"ide":{"mais":["I04","I09"],"menos":["I02"]},"ref":"Estaria errada se os reenvios vierem de pessoas querendo trocar o horário.","conf":"alta"},
{"id":14,"h":1,"sev":3,"t":"Pagamento “em análise” sem prazo","sym":"O pagamento aparece como “em análise” e ninguém diz quanto tempo leva.","ten":"A análise antifraude precisa de tempo, mas a espera precisa de horizonte.","sol":"Informar prazo típico (“até 2 horas”), o que acontece em seguida e avisar quando concluir.","c":"C22","u":"U20","e":"meso","i":"I09","m":"Contatos durante a análise","freq":2,"imp":2,"pers":2,"pf":"P06","hx":["SH3","GP2","BS1.4","ISO2","MB1","TG10"],"dom":"financas","vul":"","ag":"Ganha: o cliente e a central. Perde: o banco se compromete com prazos.","alt":"E se a análise antifraude for longa demais para valores baixos? Então a questão é a regra, não o aviso.","esc":{"micro":"Etiqueta “Em análise — até 2 h”.","meso":"Informar prazo típico (“até 2 horas”), o que acontece em seguida e avisar quando concluir.","macro":"Aprovação automática para valores baixos e clientes recorrentes."},"st":"add","sub":"Eliminar a análise manual em transações de baixo risco.","ops":["U15","U21"],"c2":{"c":"C05","t":"Prometer prazo e não cumprir piora a confiança mais que o silêncio.","mit":"Informar faixa realista e atualizar quando mudar."},"cf":"Sem intervenção, a central recebe contatos durante toda a análise.","lim":{"l":"L06","t":"Regras antifraude são definidas por compliance e não mudam fácil."},"ide":{"mais":["I09"],"menos":["I05"]},"ref":"Estaria errada se as pessoas desistirem da compra durante a análise por outros motivos.","conf":"média"},
{"id":15,"h":1,"sev":2,"t":"Limite de caracteres só no estouro","sym":"O texto é cortado ao publicar, sem aviso de que havia limite.","ten":"O limite existe por regra, mas precisa ser visto antes de ser atingido.","sol":"Contador regressivo visível que muda de cor ao se aproximar do limite.","c":"C22","u":"U20","e":"micro","i":"I04","m":"Textos cortados na publicação","freq":2,"imp":1,"pers":2,"pf":"P06","hx":["BS1.4","SH5","DN3","WC3.3","WC1.3","ISO6"],"dom":"comunicacao","vul":"cegos (leitor de tela)","ag":"Ganha: quem escreve, inclusive com leitor de tela. Perde: o campo ganha um contador que disputa atenção.","alt":"E se o limite em si for arbitrário? Talvez possa ser maior.","esc":{"micro":"Contador regressivo visível que muda de cor ao se aproximar do limite.","meso":"Salvar o texto excedente como rascunho para uma segunda publicação.","macro":"Revisar o limite com base no uso real."},"st":"add","sub":"Eliminar o corte silencioso: nunca cortar, só impedir a publicação e mostrar quanto sobra.","ops":["U25","U01"],"c2":{"c":"C17","t":"O contador anunciado a cada tecla pelo leitor de tela atrapalha.","mit":"Anunciar só em marcos (restam 20, 10, 0)."},"cf":"Sem intervenção, textos são publicados cortados no meio de uma frase.","lim":{"l":"L03","t":"Nenhum limite relevante."},"ide":{"mais":["I04"],"menos":["I03"]},"ref":"Estaria errada se as pessoas não se importarem com cortes em mensagens curtas.","conf":"alta"},
{"id":16,"h":1,"sev":3,"t":"Estoque revelado só no checkout","sym":"O produto é recusado no pagamento por falta de estoque.","ten":"O estoque muda o tempo todo, mas a pessoa precisa saber antes de decidir.","sol":"Mostrar disponibilidade na página do produto (“últimas 3 unidades”, “indisponível no tamanho G”).","c":"C12","u":"U12","e":"meso","i":"I04","m":"Carrinhos com item indisponível","freq":2,"imp":2,"pers":2,"pf":"P08","hx":["GP2","BS1.4","TG1","ISO2","SH5"],"dom":"comercio","vul":"","ag":"Ganha: quem compra e a loja, que perde menos vendas. Perde: produtos com pouco estoque podem vender menos.","alt":"E se o problema for o estoque não ser atualizado em tempo real? Então mostrar disponibilidade exibe um dado errado.","esc":{"micro":"Etiqueta “últimas unidades” na vitrine.","meso":"Mostrar disponibilidade na página do produto (“últimas 3 unidades”, “indisponível no tamanho G”).","macro":"Estoque sincronizado em tempo real entre loja física e online."},"st":"mod","sub":"Retirar da vitrine produtos indisponíveis, ou marcá-los e mandá-los para o fim.","ops":["U01","U20"],"c2":{"c":"C26","t":"“Últimas unidades” vira tática de pressão quando usada sem verdade.","mit":"Só mostrar quando for real e auditável."},"cf":"Sem intervenção, a pessoa gasta tempo escolhendo algo que não pode comprar.","lim":{"l":"L03","t":"Depende de integração com o sistema de estoque."},"ide":{"mais":["I04"],"menos":["I06"]},"ref":"Estaria errada se o estoque for alterado entre a vitrine e o pagamento por outras compras simultâneas.","conf":"alta"},
{"id":17,"h":1,"sev":2,"t":"Download sem sinal de início","sym":"No portal, a pessoa clica em “Baixar certidão” e nada parece acontecer; clica mais três vezes.","ten":"O download acontece no navegador, mas o clique precisa de resposta na página.","sol":"Mensagem “Download iniciado” com nome do arquivo e link alternativo caso não comece.","c":"C01","u":"U01","e":"micro","i":"I09","m":"Downloads duplicados","freq":3,"imp":1,"pers":2,"pf":"P01","hx":["DN2","BS1.4","SH3","ISO2","WC4.1"],"dom":"publico","vul":"baixa escolaridade","ag":"Ganha: quem emite documentos. Perde: mais uma mensagem na tela a cada download.","alt":"E se o problema for o documento abrir numa aba invisível, e não o download?","esc":{"micro":"Mensagem “Download iniciado” com nome do arquivo e link alternativo caso não comece.","meso":"Mostrar o documento no próprio navegador, com botão de salvar.","macro":"Enviar o documento também para o e-mail ou para a carteira digital do governo."},"st":"add","sub":"Remover a necessidade de baixar: exibir a certidão com código de validação online.","ops":["U16","U22"],"c2":{"c":"C34","t":"Mensagens de download aparecem até quando o navegador já mostrou o próprio aviso.","mit":"Mostrar só na primeira vez e sempre com link alternativo."},"cf":"Sem intervenção, a mesma certidão é baixada várias vezes e se perde nas pastas.","lim":{"l":"L03","t":"O comportamento do download depende do navegador."},"ide":{"mais":["I09"],"menos":["I03"]},"ref":"Estaria errada se as pessoas souberem que baixaram, mas não encontrarem o arquivo.","conf":"alta"},
{"id":18,"h":1,"sev":3,"t":"Sincronização entre dispositivos sem status","sym":"A lista de compras da família mostra itens diferentes em cada celular e ninguém sabe qual está certa.","ten":"Sincronizar é automático, mas o atraso precisa ser visível.","sol":"Indicador de sincronização (sincronizado, pendente, falhou) com horário da última atualização.","c":"C35","u":"U03","e":"macro","i":"I09","m":"Conflitos de edição","freq":2,"imp":2,"pers":2,"pf":"P04","hx":["MB1","GP2","DN1","ISO2","TG15","SH3"],"dom":"casa","vul":"","ag":"Ganha: a família que divide a lista. Perde: sem conexão, a lista fica inacessível se não houver cópia local.","alt":"E se o problema for a ausência de sincronização em si, e não só a falta de status?","esc":{"micro":"Selo “sincronizado há 2 min” na lista.","meso":"Mostrar quem alterou cada item e quando.","macro":"Indicador de sincronização (sincronizado, pendente, falhou) com horário da última atualização."},"st":"add","sub":"Eliminar cópias locais: a lista vive num só lugar, e os aparelhos só a exibem.","ops":["U01","U19"],"c2":{"c":"C30","t":"Sem conexão, a lista fica inacessível se não houver cópia local.","mit":"Cópia local somente leitura quando estiver offline."},"cf":"Sem intervenção, a família compra itens repetidos ou esquece outros.","lim":{"l":"L03","t":"Depende de rede em todos os aparelhos."},"ide":{"mais":["I09","I04"],"menos":["I03"]},"ref":"Estaria errada se as diferenças vierem de edições simultâneas, e não de atraso de sincronização.","conf":"média"},
{"id":19,"h":1,"sev":4,"t":"Edição simultânea às cegas","sym":"Duas pessoas editam a mesma planilha e uma sobrescreve a outra.","ten":"A colaboração deve ser livre, mas cada um precisa saber que não está sozinho.","sol":"Avatares de quem está editando, cursores coloridos e aviso ao abrir item em uso.","c":"C27","u":"U03","e":"meso","i":"I09","m":"Alterações sobrescritas","freq":3,"imp":3,"pers":2,"pf":"P08","hx":["MB7","DN1","SH3","ISO5","TG13","GP2"],"dom":"trabalho","vul":"","ag":"Ganha: equipes que editam juntas. Perde: parte da privacidade de quem edita, que fica visível.","alt":"E se o problema for a falta de mesclagem, e não de visibilidade?","esc":{"micro":"Aviso ao abrir uma célula em uso.","meso":"Avatares de quem está editando, cursores coloridos e aviso ao abrir item em uso.","macro":"Mesclagem automática por célula com histórico de conflitos."},"st":"add","sub":"Retirar a gravação por arquivo inteiro: gravar por célula, eliminando a sobrescrita.","ops":["U01","U24"],"c2":{"c":"C26","t":"Ver quem está editando pode gerar pressão ou vigilância.","mit":"Mostrar presença sem registrar tempo de atividade."},"cf":"Sem intervenção, alterações se perdem e a equipe passa a desconfiar da planilha.","lim":{"l":"L03","t":"Edição em tempo real exige infraestrutura de colaboração."},"ide":{"mais":["I09","I04"],"menos":["I07"]},"ref":"Estaria errada se as sobrescritas vierem de importações automáticas, e não de pessoas.","conf":"alta"},
{"id":20,"h":1,"sev":3,"t":"Frete surge só no último passo","sym":"O total aumenta 30% na tela final, sem destaque.","ten":"O frete depende do endereço, mas o custo total precisa ser previsível.","sol":"Mudar a fronteira do “preço”: exibir o valor com frete estimado pelo CEP desde a vitrine, sem acréscimo surpresa no fim.","c":"C26","u":"U05","e":"macro","i":"I06","m":"Abandono na última etapa","freq":3,"imp":2,"pers":2,"pf":"P09","hx":["DP3","GP2","SH3","ISO3","LX8","TG1"],"dom":"comercio","vul":"","ag":"Ganha: quem compra. Perde: a loja perde o “preço baixo” de vitrine.","alt":"E se a surpresa for uma estratégia deliberada? Então o problema é ético, não de interface.","esc":{"micro":"Estimar frete pelo CEP no carrinho.","meso":"Frete estimado já na página do produto.","macro":"Mudar a fronteira do “preço”: exibir o valor com frete estimado pelo CEP desde a vitrine, sem acréscimo surpresa no fim."},"st":"mod","sub":"Remover a surpresa: preço com frete desde o início, sem acréscimo no fim.","ops":["U20","U28"],"c2":{"c":"C20","t":"Preço com frete parece mais caro que o de concorrentes que escondem o frete.","mit":"Destacar “preço final, sem surpresas” como diferencial."},"cf":"Sem intervenção, o abandono na última etapa continua e a marca é vista como enganosa.","lim":{"l":"L06","t":"Mudar a política de preço depende do comercial."},"ide":{"mais":["I06","I09"],"menos":["I02"]},"ref":"Estaria errada se o abandono vier de frete alto, e não de frete inesperado.","conf":"alta"},
{"id":21,"h":1,"sev":2,"t":"Busca lenta sem indicador","sym":"A busca com IA do catálogo demora 6 segundos e a lista antiga continua na tela, como se nada tivesse acontecido.","ten":"Algumas buscas são pesadas, mas a espera não pode parecer falha.","sol":"Indicador de carregamento no campo, lista anterior esmaecida e resultados parciais quando possível.","c":"C15","u":"U08","e":"micro","i":"I09","m":"Buscas repetidas","freq":2,"imp":1,"pers":2,"pf":"P02","hx":["TG10","LX6","BS1.4","IA2","ISO2"],"dom":"ia","vul":"","ag":"Ganha: quem busca. Perde: resultados parciais podem mudar de ordem quando a IA termina e confundir.","alt":"E se a busca por IA for lenta por natureza? Talvez valha a pena oferecer primeiro a busca simples.","esc":{"micro":"Indicador de carregamento no campo, lista anterior esmaecida e resultados parciais quando possível.","meso":"Resultado rápido por palavra-chave primeiro, e a resposta da IA depois, quando pronta.","macro":"Pré-calcular buscas frequentes."},"st":"mod","sub":"Retirar a etapa de IA das buscas simples, deixando-a sob demanda.","ops":["U01","U26"],"c2":{"c":"C35","t":"Resultados parciais podem mudar de ordem quando a IA termina e confundir.","mit":"Não reordenar o que já foi visto; acrescentar abaixo."},"cf":"Sem intervenção, as pessoas repetem a busca achando que falhou.","lim":{"l":"L03","t":"A latência da IA depende do modelo e da infraestrutura."},"ide":{"mais":["I09","I02"],"menos":["I04"]},"ref":"Estaria errada se as repetições forem para refinar a busca, e não por espera.","conf":"média"},
{"id":22,"h":1,"sev":4,"t":"Modo de edição invisível","sym":"No prontuário, a médica digita achando que está só lendo e altera a anotação de outro profissional.","ten":"Ler e editar são estados diferentes, mas a tela parece igual nos dois.","sol":"Sinalizar o modo com rótulo fixo (“Editando”), cor de fundo e botão explícito para alternar.","c":"C05","u":"U09","e":"micro","i":"I09","m":"Edições acidentais","freq":2,"imp":3,"pers":2,"pf":"P01","hx":["DN1","DN3","BS3.1","ISO5","SH5","TG15"],"dom":"saude","vul":"","ag":"Ganha: pacientes, pela segurança do prontuário. Perde: um clique a mais para editar.","alt":"E se o modo de edição devesse ser mais difícil de ativar, e não só mais visível?","esc":{"micro":"Sinalizar o modo com rótulo fixo (“Editando”), cor de fundo e botão explícito para alternar.","meso":"Edição com registro de autor e motivo para campos críticos.","macro":"Auditoria de alterações do prontuário."},"st":"mod","sub":"Remover a edição direta: o prontuário abre sempre em leitura.","ops":["U21","U01"],"c2":{"c":"C31","t":"Exigir ativação explícita atrasa quem precisa corrigir rápido.","mit":"Atalho de teclado para editar e voltar."},"cf":"Sem intervenção, anotações clínicas são alteradas sem querer.","lim":{"l":"L06","t":"Normas de prontuário exigem rastreio de alterações."},"ide":{"mais":["I09","I05","I10"],"menos":["I02"]},"ref":"Estaria errada se as alterações vierem de duas pessoas no mesmo registro, e não de confusão de modo.","conf":"alta"},
{"id":23,"h":1,"sev":4,"t":"Câmera ou microfone ativos sem aviso","sym":"Na teleconsulta, o áudio continua sendo transmitido depois que o paciente acha que saiu.","ten":"A transmissão precisa funcionar em segundo plano, mas a privacidade exige consciência.","sol":"Indicador permanente e chamativo enquanto houver captura, com botão de encerrar sempre visível.","c":"C03","u":"U01","e":"micro","i":"I05","m":"Transmissões inadvertidas","freq":2,"imp":3,"pers":2,"pf":"P13","hx":["MB7","DN1","TG2","ISO5","SH7","WC1.4"],"dom":"saude","vul":"","ag":"Ganha: paciente e profissional, em privacidade. Perde: um indicador permanente que pode distrair durante a consulta.","alt":"E se o problema for a chamada não ter fim claro?","esc":{"micro":"Indicador permanente e chamativo enquanto houver captura, com botão de encerrar sempre visível.","meso":"Botão de sair que encerra captura e chamada ao mesmo tempo.","macro":"Política de encerramento automático quando não houver mais participantes."},"st":"add","sub":"Não manter câmera e microfone ativos depois de sair da sala.","ops":["U24","U23"],"c2":{"c":"C17","t":"Indicadores muito chamativos distraem durante a consulta.","mit":"Indicador fixo, discreto, que se destaca só quando a janela está em segundo plano."},"cf":"Sem intervenção, conversas privadas vazam depois da teleconsulta.","lim":{"l":"L03","t":"Depende de permissões do sistema operacional."},"ide":{"mais":["I05"],"menos":["I03"]},"ref":"Estaria errada se as transmissões forem de outros apps.","conf":"alta"},
{"id":24,"h":1,"sev":3,"t":"Cota esgotada sem aviso prévio","sym":"O armazenamento lota e os e-mails param de chegar sem alerta.","ten":"O plano tem limites, mas ninguém deve descobri-los pela falha.","sol":"Alertas em 80% e 95% da cota, com o que ocupa mais espaço e como liberar.","c":"C18","u":"U20","e":"macro","i":"I11","m":"Bloqueios por cota","freq":2,"imp":2,"pers":3,"pf":"P06","hx":["GP1","BS1.1","ISO2","TG1","SH3"],"dom":"comunicacao","vul":"","ag":"Ganha: quem depende do e-mail. Perde: o provedor pode vender menos upgrades por urgência.","alt":"E se a cota for pequena demais para o uso atual?","esc":{"micro":"Barra de uso sempre visível no menu.","meso":"Alertas em 80% e 95%, com o que ocupa mais espaço.","macro":"Alertas em 80% e 95% da cota, com o que ocupa mais espaço e como liberar."},"st":"add","sub":"Remover anexos antigos e duplicados automaticamente, com aviso.","ops":["U18","U15"],"c2":{"c":"C26","t":"Alertas podem ser usados para empurrar planos pagos.","mit":"Oferecer primeiro a limpeza gratuita."},"cf":"Sem intervenção, e-mails importantes são devolvidos sem que ninguém perceba.","lim":{"l":"L04","t":"Espaço de armazenamento tem custo."},"ide":{"mais":["I11","I09"],"menos":["I03"]},"ref":"Estaria errada se as pessoas virem o alerta e o ignorarem.","conf":"alta"},
{"id":25,"h":1,"sev":3,"t":"Fila de atendimento sem posição","sym":"No atendimento online da previdência, aparece só “Aguarde, você será atendido” — por quanto tempo?","ten":"A fila é inevitável, mas a incerteza pesa mais que a espera.","sol":"Mostrar posição e tempo estimado e oferecer retorno no horário marcado, sem manter a pessoa presa na espera.","c":"C31","u":"U13","e":"meso","i":"I09","m":"Desistências na fila","freq":3,"imp":2,"pers":2,"pf":"P02","hx":["SH3","GP2","BS1.4","LX8","ISO5"],"dom":"publico","vul":"idosos","ag":"Ganha: quem espera e o órgão, que atende com menos pressão. Perde: tempo estimado errado frustra mais que nenhuma estimativa.","alt":"E se a fila existir porque o serviço exige atendimento humano sem necessidade?","esc":{"micro":"Posição e tempo estimado na tela.","meso":"Mostrar posição e tempo estimado e oferecer retorno no horário marcado, sem manter a pessoa presa na espera.","macro":"Resolver os pedidos simples por autoatendimento."},"st":"mod","sub":"Retirar da fila quem pode resolver sozinho, com triagem antes.","ops":["U01","U16"],"c2":{"c":"C27","t":"Tempo estimado errado frustra mais que nenhuma estimativa.","mit":"Mostrar faixa e atualizar ao vivo."},"cf":"Sem intervenção, as pessoas desistem ou entram em várias filas ao mesmo tempo.","lim":{"l":"L04","t":"Depende do número de atendentes disponíveis."},"ide":{"mais":["I09"],"menos":["I02"]},"ref":"Estaria errada se as desistências forem por falta de tempo, e não por incerteza.","conf":"alta"},
{"id":26,"h":1,"sev":4,"t":"Pendência de conta escondida","sym":"A conta não pode sacar, mas o motivo (documento pendente) está enterrado no perfil.","ten":"O sistema restringe por segurança, mas a pessoa precisa saber o que falta.","sol":"Reorientar o objetivo: verificar a renda por base autorizada (com consentimento) e só pedir comprovante quando a verificação falhar.","c":"C28","u":"U06","e":"macro","i":"I09","m":"Tentativas bloqueadas por pendência","freq":2,"imp":3,"pers":2,"pf":"P16","hx":["GP1","BS2.2","ISO1","DN1","SH3"],"dom":"financas","vul":"baixa renda","ag":"Ganha: clientes sem comprovante formal. Perde: o banco precisa integrar bases de dados.","alt":"E se o comprovante for exigido só porque sempre foi? Então o objetivo real é verificar a renda.","esc":{"micro":"Faixa no topo com o que falta.","meso":"Envio do documento direto pelo celular.","macro":"Reorientar o objetivo: verificar a renda por base autorizada (com consentimento) e só pedir comprovante quando a verificação falhar."},"st":"sub","sub":"A própria solução é subtrativa: remove a exigência do comprovante.","ops":["U01","U29"],"c2":{"c":"C05","t":"Verificar pela base de dados exige consentimento para acessar informações pessoais.","mit":"Pedir consentimento explícito e oferecer o envio manual como alternativa."},"cf":"Sem intervenção, clientes com renda informal ficam bloqueados sem saber por quê.","lim":{"l":"L06","t":"Depende de regulação e convênios para consultar bases."},"ide":{"mais":["I09","I07","I06"],"menos":["I05"]},"ref":"Estaria errada se a pendência for de identidade, e não de renda.","conf":"média"},
{"id":27,"h":1,"sev":3,"t":"Chave liga/desliga ambígua","sym":"No app da casa, a chave “Ferro de passar” não deixa claro se está ligado ou desligado.","ten":"O controle deve ser compacto, mas o estado precisa ser inequívoco.","sol":"Chave com estado visual claro e texto do estado atual (“Ativadas”).","c":"C02","u":"U16","e":"micro","i":"I03","m":"Configurações invertidas","freq":3,"imp":2,"pers":2,"pf":"P01","hx":["DN4","DN7","BS7","TG3","WC1.4","MB3"],"dom":"casa","vul":"idosos","ag":"Ganha: quem controla a casa pelo celular. Perde: nada.","alt":"E se o problema for o estado real do aparelho ser desconhecido pelo app?","esc":{"micro":"Chave com estado visual claro e texto do estado atual (“Ativadas”).","meso":"Tela de cada aparelho com estado atual e último comando.","macro":"O próprio aparelho sinaliza o estado (luz)."},"st":"add","sub":"Tirar a ambiguidade removendo o rótulo fixo: o texto passa a ser o próprio estado.","ops":["U01","U12"],"c2":{"c":"C09","t":"Se o aparelho não responder, o app mostra um estado falso.","mit":"Mostrar “sem resposta” quando não houver confirmação."},"cf":"Sem intervenção, a pessoa sai de casa achando que desligou o aparelho.","lim":{"l":"L03","t":"Depende de o aparelho informar o estado."},"ide":{"mais":["I03"],"menos":[]},"ref":"Estaria errada se a confusão vier de o aparelho demorar a responder.","conf":"média"},
{"id":28,"h":1,"sev":2,"t":"Arrastar sem prévia do destino","sym":"No quadro de tarefas da equipe, ao arrastar um cartão não se sabe onde ele vai cair.","ten":"Arrastar é rápido, mas o resultado precisa ser antecipado.","sol":"Mostrar a posição de destino (espaço aberto, linha guia) durante o arrasto.","c":"C34","u":"U25","e":"micro","i":"I04","m":"Reposicionamentos corrigidos","freq":2,"imp":2,"pers":1,"pf":"P01","hx":["DN2","BS1.4","TG8","ISO5","SH6"],"dom":"trabalho","vul":"","ag":"Ganha: quem organiza tarefas. Perde: prévias exageradas atrapalham a visão do quadro.","alt":"E se arrastar não for o meio certo? Talvez “Mover para…” seja mais preciso.","esc":{"micro":"Mostrar a posição de destino (espaço aberto, linha guia) durante o arrasto.","meso":"Menu “Mover para” com lista de colunas.","macro":"Arrastar também disponível por teclado."},"st":"add","sub":"Remover a exigência de precisão: soltar em qualquer ponto da coluna encaixa no lugar certo.","ops":["U24","U22"],"c2":{"c":"C17","t":"Prévias exageradas atrapalham a visão do quadro.","mit":"Linha fina de destino."},"cf":"Sem intervenção, cartões vão para o lugar errado e ninguém percebe.","lim":{"l":"L07","t":"Arrastar é difícil para quem tem limitação motora."},"ide":{"mais":["I04"],"menos":["I03"]},"ref":"Estaria errada se os erros vierem de colunas parecidas, e não da falta de prévia.","conf":"alta"},
{"id":29,"h":1,"sev":1,"t":"Disponibilidade de nome só no envio","sym":"O nome de usuário é recusado como “já existe” depois de preencher tudo.","ten":"A verificação depende do servidor, mas pode acontecer enquanto se digita.","sol":"Checar disponibilidade em tempo real e sugerir variações livres.","c":"C16","u":"U25","e":"micro","i":"I02","m":"Tentativas até concluir o cadastro","freq":2,"imp":1,"pers":1,"pf":"P03","hx":["BS1.4","SH5","WC3.3","LX7","ISO6"],"dom":"comunicacao","vul":"","ag":"Ganha: quem cria a conta. Perde: nada.","alt":"E se nomes únicos não forem necessários?","esc":{"micro":"Checar disponibilidade em tempo real e sugerir variações livres.","meso":"Aceitar nomes iguais, diferenciados por um número.","macro":"Identidade separada do nome de exibição."},"st":"add","sub":"Remover a exigência de nome único (nome + número discreto).","ops":["U20","U06"],"c2":{"c":"C16","t":"Sugestões automáticas podem gerar nomes estranhos ou ofensivos.","mit":"Filtrar sugestões e deixar editar."},"cf":"Sem intervenção, as pessoas tentam várias vezes e desistem do cadastro.","lim":{"l":"L01","t":"Se o nome é identificador, precisa ser único."},"ide":{"mais":["I02"],"menos":[]},"ref":"Estaria errada se as tentativas vierem de regras de formato, e não de nomes em uso.","conf":"alta"},
{"id":30,"h":1,"sev":3,"t":"Prazo de oferta sem relógio","sym":"“Oferta por tempo limitado” — até quando?","ten":"A urgência vende, mas a informação precisa ser verdadeira e precisa.","sol":"Mostrar data e hora exatas do fim, sem contadores falsos que reiniciam.","c":"C26","u":"U28","e":"micro","i":"I06","m":"Reclamações sobre preço encerrado","freq":2,"imp":2,"pers":2,"pf":"P09","hx":["DP3","DP4","GP2","TG2","ISO7"],"dom":"comercio","vul":"","ag":"Ganha: a confiança do cliente. Perde: a urgência artificial deixa de vender.","alt":"E se a oferta não precisar de prazo?","esc":{"micro":"Mostrar data e hora exatas do fim, sem contadores falsos que reiniciam.","meso":"Página de ofertas com datas reais de início e fim.","macro":"Auditoria de práticas de urgência."},"st":"mod","sub":"Remover contadores falsos que reiniciam.","ops":["U01","U30"],"c2":{"c":"C20","t":"Sem urgência, algumas vendas por impulso deixam de ocorrer.","mit":"Aceitar a perda em troca de confiança."},"cf":"Sem intervenção, a confiança cai e surgem reclamações de publicidade enganosa.","lim":{"l":"L06","t":"Código de defesa do consumidor."},"ide":{"mais":["I06","I09"],"menos":["I02"]},"ref":"Estaria errada se, em teste de compra, o contador reiniciando não mudar a confiança declarada nem a taxa de conversão.","conf":"média"},
{"id":31,"h":1,"sev":3,"t":"Atualização que reinicia sem avisar","sym":"O GPS do carro reinicia para atualizar no meio do trajeto.","ten":"O sistema precisa se atualizar, mas não às custas do trabalho da pessoa.","sol":"Atualizar em segundo plano e aplicar só quando o carro for desligado, sem reiniciar durante o uso.","c":"C32","u":"U33","e":"macro","i":"I07","m":"Trabalho interrompido por atualização","freq":2,"imp":2,"pers":2,"pf":"P14","hx":["BS3.2","SH7","ISO5","TG13","MB8"],"dom":"mobilidade","vul":"","ag":"Ganha: quem dirige. Perde: atualizações demoram mais a chegar.","alt":"E se a atualização não precisasse reiniciar nada?","esc":{"micro":"Aviso “atualiza ao desligar o carro”.","meso":"Atualizar só com o carro parado.","macro":"Atualizar em segundo plano e aplicar só quando o carro for desligado, sem reiniciar durante o uso."},"st":"sub","sub":"A própria solução é subtrativa: remove o reinício durante o trajeto.","ops":["U08","U20"],"c2":{"c":"C36","t":"Adiar atualizações deixa correções de segurança pendentes.","mit":"Forçar apenas correções críticas, com o carro parado."},"cf":"Sem intervenção, motoristas perdem a navegação no meio do trajeto.","lim":{"l":"L03","t":"Depende de o sistema suportar atualização em segundo plano."},"ide":{"mais":["I07","I05"],"menos":["I12"]},"ref":"Estaria errada se as reinicializações forem falhas, e não atualizações.","conf":"média"},
{"id":32,"h":1,"sev":4,"t":"Instabilidade não comunicada","sym":"O app do banco está fora do ar e a pessoa acha que o problema é no seu celular.","ten":"A equipe já sabe da falha, mas a informação não chega a quem usa.","sol":"Página de status pública e aviso na própria interface durante incidentes.","c":"C09","u":"U12","e":"macro","i":"I09","m":"Chamados durante incidentes","freq":2,"imp":3,"pers":2,"pf":"P04","hx":["MB1","SH3","GP2","ISO2","TG15"],"dom":"financas","vul":"","ag":"Ganha: clientes e suporte. Perde: o banco expõe publicamente as falhas.","alt":"E se as falhas forem frequentes demais? Então comunicar não basta.","esc":{"micro":"Faixa de aviso dentro do app durante incidentes.","meso":"Página de status com histórico.","macro":"Página de status pública e aviso na própria interface durante incidentes."},"st":"add","sub":"Remover chamadas desnecessárias ao servidor que tornam o app frágil.","ops":["U01","U22"],"c2":{"c":"C26","t":"Expor falhas publicamente afeta a imagem da empresa.","mit":"Comunicar com clareza e prazos, mostrando também a solução."},"cf":"Sem intervenção, clientes reinstalam o app e sobrecarregam o suporte durante as quedas.","lim":{"l":"L06","t":"Comunicação de incidentes pode depender do jurídico."},"ide":{"mais":["I09"],"menos":[]},"ref":"Estaria errada se os chamados forem de outros problemas.","conf":"alta"},
{"id":33,"h":1,"sev":3,"t":"Mensagem sem status de entrega","sym":"Não se sabe se a mensagem foi enviada, entregue ou lida.","ten":"A troca é assíncrona, mas o remetente precisa saber o que aconteceu.","sol":"Marcadores de estado (enviando, enviado, entregue, falhou) com opção de reenviar.","c":"C33","u":"U19","e":"micro","i":"I09","m":"Mensagens reenviadas","freq":3,"imp":2,"pers":2,"pf":"P01","hx":["DN2","SH3","BS1.4","MB1","ISO2"],"dom":"comunicacao","vul":"","ag":"Ganha: quem envia mensagens. Perde: parte da privacidade de quem lê.","alt":"E se o status de leitura criar pressão social?","esc":{"micro":"Marcadores de estado (enviando, enviado, entregue, falhou) com opção de reenviar.","meso":"Opção de ocultar a confirmação de leitura.","macro":"Política clara sobre o que é compartilhado."},"st":"add","sub":"Remover a confirmação de leitura por padrão, mantendo só a de entrega.","ops":["U14","U01"],"c2":{"c":"C26","t":"Saber que a mensagem foi lida gera cobrança por resposta.","mit":"Deixar a confirmação de leitura sob controle de cada pessoa."},"cf":"Sem intervenção, mensagens são reenviadas e conversas se duplicam.","lim":{"l":"L03","t":"Depende de o servidor registrar a entrega."},"ide":{"mais":["I09"],"menos":["I07"]},"ref":"Estaria errada se os reenvios forem por impaciência, e não por incerteza.","conf":"alta"},
{"id":34,"h":1,"sev":3,"t":"Rolagem infinita sem fim aparente","sym":"O feed recomendado pela IA nunca termina; a pessoa rola por minutos sem saber se já viu tudo.","ten":"Carregar sob demanda economiza, mas o limite da lista precisa ser visível.","sol":"Carregar em blocos com “Mostrar mais” e mostrar claramente quando não houver mais novidades.","c":"C19","u":"U31","e":"micro","i":"I09","m":"Rolagens até desistir","freq":2,"imp":2,"pers":2,"pf":"P16","hx":["DP1","IA17","GP8","LX11","ISO5","TG2"],"dom":"ia","vul":"","ag":"Ganha: quem usa, que retoma o controle do tempo. Perde: a plataforma, em tempo de uso.","alt":"E se o problema for o feed infinito ser uma estratégia de retenção?","esc":{"micro":"Carregar em blocos com “Mostrar mais” e mostrar claramente quando não houver mais novidades.","meso":"Aviso “Você está em dia” quando acabarem as novidades.","macro":"Limite de tempo configurável pela pessoa."},"st":"sub","sub":"A própria solução é subtrativa: substitui a rolagem infinita por blocos com fim.","ops":["U14","U28"],"c2":{"c":"C26","t":"Menos tempo de uso reduz receita de anúncios.","mit":"Medir satisfação e retorno, não só tempo."},"cf":"Sem intervenção, as pessoas relatam uso compulsivo e cansaço.","lim":{"l":"L06","t":"O modelo de negócio depende de tempo de tela."},"ide":{"mais":["I09","I07"],"menos":["I02"]},"ref":"Estaria errada se as pessoas preferirem a rolagem contínua em testes.","conf":"média"},
{"id":35,"h":1,"sev":4,"t":"Seleção múltipla sem contagem","sym":"A professora aplica a nota a 12 estudantes quando achava que eram 3.","ten":"Selecionar em listas longas esconde itens fora da tela.","sol":"Barra fixa com “12 selecionados”, lista dos selecionados e opção de limpar.","c":"C34","u":"U01","e":"micro","i":"I04","m":"Ações aplicadas a itens errados","freq":2,"imp":3,"pers":2,"pf":"P01","hx":["BS1.4","SH8","GP2","DN1","ISO6"],"dom":"educacao","vul":"","ag":"Ganha: professores e estudantes. Perde: barras fixas ocupam espaço em telas pequenas.","alt":"E se a seleção em lote for arriscada demais para notas?","esc":{"micro":"Barra fixa com “12 selecionados”, lista dos selecionados e opção de limpar.","meso":"Tela de revisão antes de publicar notas em lote.","macro":"Registro de quem publicou as notas e opção de corrigir."},"st":"add","sub":"Remover a seleção implícita de itens fora da tela.","ops":["U25","U24"],"c2":{"c":"C17","t":"Barras fixas ocupam espaço em telas pequenas.","mit":"Barra compacta que só aparece com seleção ativa."},"cf":"Sem intervenção, notas vão para os estudantes errados.","lim":{"l":"L07","t":"Professores lidam com turmas grandes."},"ide":{"mais":["I04"],"menos":["I02"]},"ref":"Estaria errada se os erros vierem da lista de estudantes desatualizada.","conf":"alta"},
{"id":36,"h":1,"sev":2,"t":"Cupom aplicado sem efeito visível","sym":"O cupom é aceito, mas o total parece o mesmo.","ten":"O desconto é calculado, mas precisa ser mostrado.","sol":"Linha de desconto destacada no resumo, com valor economizado e condições.","c":"C04","u":"U19","e":"micro","i":"I09","m":"Contatos sobre cupons","freq":2,"imp":1,"pers":2,"pf":"P01","hx":["DN2","SH3","BS1.4","GP2"],"dom":"comercio","vul":"","ag":"Ganha: quem compra. Perde: nada.","alt":"E se o cupom tiver sido aplicado a outro item, e não ao total?","esc":{"micro":"Linha de desconto destacada no resumo, com valor economizado e condições.","meso":"Explicar a regra do cupom e em quais itens vale.","macro":"Regras de cupom simples e padronizadas."},"st":"add","sub":"Remover cupons com regras complexas que ninguém entende.","ops":["U01","U30"],"c2":{"c":"C35","t":"Mostrar a economia de forma exagerada parece manipulação.","mit":"Valor exato, sem destaques inflados."},"cf":"Sem intervenção, surgem contatos sobre cupons que “não funcionam”.","lim":{"l":"L03","t":"Nenhum limite relevante."},"ide":{"mais":["I09"],"menos":[]},"ref":"Estaria errada se o desconto não tiver sido aplicado de fato.","conf":"alta"},
{"id":37,"h":1,"sev":3,"t":"Dispositivo conectado sem estado","sym":"No app da casa, não se sabe se a caixa de som está pareada ou não.","ten":"A conexão acontece em outra camada, mas a interface precisa refleti-la.","sol":"Indicador de conexão com nome do dispositivo e botão de reconectar.","c":"C09","u":"U16","e":"micro","i":"I09","m":"Tentativas de pareamento","freq":2,"imp":2,"pers":2,"pf":"P04","hx":["MB1","DN1","DN2","ISO2","TG15"],"dom":"casa","vul":"","ag":"Ganha: quem usa aparelhos conectados. Perde: indicadores de cada aparelho poluem a tela.","alt":"E se o problema for o pareamento instável, e não a falta de indicação?","esc":{"micro":"Indicador de conexão com nome do dispositivo e botão de reconectar.","meso":"Tela de diagnóstico com passos para reconectar.","macro":"Protocolo de conexão mais estável."},"st":"add","sub":"Remover pareamentos antigos que disputam a conexão.","ops":["U01","U22"],"c2":{"c":"C17","t":"Indicadores de cada aparelho poluem a tela.","mit":"Resumo com os aparelhos com problema no topo."},"cf":"Sem intervenção, a pessoa tenta parear várias vezes.","lim":{"l":"L02","t":"Interferências físicas afetam a conexão sem fio."},"ide":{"mais":["I09"],"menos":["I03"]},"ref":"Estaria errada se o aparelho estiver conectado, mas com falha de outro tipo.","conf":"média"},
{"id":38,"h":1,"sev":4,"t":"Alterações não salvas invisíveis","sym":"Ao editar o plano de aula, não há sinal de mudanças pendentes; a professora fecha a aba e perde tudo.","ten":"Salvar pode ser manual, mas o risco precisa estar visível.","sol":"Eliminar o estado “não salvo”: salvar automaticamente cada alteração e manter histórico de versões.","c":"C06","u":"U16","e":"micro","i":"I10","m":"Perdas por esquecer de salvar","freq":2,"imp":3,"pers":2,"pf":"P01","hx":["TG13","SH6","ISO6","BS5.1","GP1"],"dom":"educacao","vul":"","ag":"Ganha: professores. Perde: nada.","alt":"E se o salvamento manual existir por um motivo (versões)?","esc":{"micro":"Eliminar o estado “não salvo”: salvar automaticamente cada alteração e manter histórico de versões.","meso":"Histórico de versões do plano de aula.","macro":"Salvamento automático como padrão de toda a plataforma."},"st":"sub","sub":"A própria solução é subtrativa: elimina o estado “não salvo”.","ops":["U24","U36"],"c2":{"c":"C08","t":"Salvar automaticamente grava também mudanças que a pessoa desejaria descartar.","mit":"Histórico de versões e “Descartar alterações da sessão”."},"cf":"Sem intervenção, planos de aula se perdem ao fechar a aba.","lim":{"l":"L03","t":"Exige armazenamento de versões."},"ide":{"mais":["I10","I05"],"menos":[]},"ref":"Estaria errada se as perdas forem por fechar o navegador de propósito.","conf":"alta"},
{"id":39,"h":1,"sev":3,"t":"Agendamento sem lembrete","sym":"A consulta foi marcada há um mês e a paciente esqueceu.","ten":"O agendamento é feito cedo, mas o compromisso acontece tarde.","sol":"Lembretes configuráveis (1 dia e 1 hora antes) com opção de confirmar ou remarcar.","c":"C33","u":"U20","e":"meso","i":"I04","m":"Faltas em agendamentos","freq":3,"imp":2,"pers":2,"pf":"P06","hx":["TG1","GP1","SH8","BS1.1","ISO1"],"dom":"saude","vul":"idosos","ag":"Ganha: pacientes e a unidade, com menos faltas. Perde: custo de mensagens.","alt":"E se as faltas vierem de dificuldade de ir, e não de esquecimento?","esc":{"micro":"Lembrete no app um dia antes, com botões “Confirmar” e “Remarcar”.","meso":"Lembretes configuráveis (1 dia e 1 hora antes) com opção de confirmar ou remarcar.","macro":"Transporte ou teleconsulta como alternativa."},"st":"add","sub":"Remover o agendamento distante: marcar mais perto da data quando possível.","ops":["U22","U14"],"c2":{"c":"C17","t":"Lembretes demais viram ruído e são ignorados.","mit":"Dois lembretes, com opção de confirmar ou remarcar."},"cf":"Sem intervenção, as faltas continuam desperdiçando vagas.","lim":{"l":"L04","t":"Custo de SMS e telefone."},"ide":{"mais":["I04"],"menos":["I02"]},"ref":"Estaria errada se as faltas vierem de problemas de transporte.","conf":"alta"},
{"id":40,"h":1,"sev":3,"t":"Consumo de dados móveis sem aviso","sym":"O vídeo em alta resolução consome o pacote de dados do celular.","ten":"A qualidade encanta, mas o custo é da pessoa.","sol":"Em rede móvel, usar qualidade reduzida por padrão, avisar do consumo e deixar a pessoa escolher mais qualidade.","c":"C18","u":"U21","e":"macro","i":"I11","m":"Reclamações sobre consumo","freq":3,"imp":2,"pers":2,"pf":"P14","hx":["MB6","MB1","TG5","GP1","ISO5"],"dom":"comunicacao","vul":"baixa renda","ag":"Ganha: quem tem pacote de dados limitado. Perde: a qualidade de vídeo padrão cai no celular.","alt":"E se a pessoa não souber quanto consome?","esc":{"micro":"Aviso ao dar play em rede móvel.","meso":"Configuração de qualidade por tipo de rede.","macro":"Em rede móvel, usar qualidade reduzida por padrão, avisar do consumo e deixar a pessoa escolher mais qualidade."},"st":"sub","sub":"A própria solução é subtrativa: remove a alta resolução como padrão no celular.","ops":["U01","U14"],"c2":{"c":"C21","t":"Quem tem dados ilimitados passa a ver qualidade pior sem querer.","mit":"Lembrar a escolha de cada pessoa."},"cf":"Sem intervenção, o pacote acaba no meio do mês.","lim":{"l":"L04","t":"Depende do plano de dados da pessoa."},"ide":{"mais":["I11","I06"],"menos":["I01"]},"ref":"Estaria errada se o consumo vier de outros apps.","conf":"alta"},
{"id":41,"h":1,"sev":3,"t":"Processo de aprovação sem rastreio","sym":"O processo administrativo está parado e o cidadão não sabe em qual setor.","ten":"A aprovação passa por várias pessoas, mas o caminho é opaco.","sol":"Reorganizar o fluxo mostrando cada etapa com o responsável nomeado e o tempo parado.","c":"C12","u":"U11","e":"macro","i":"I09","m":"Tempo parado por etapa","freq":2,"imp":2,"pers":3,"pf":"P08","hx":["GP3","TG15","ISO2","SH3","DN1"],"dom":"publico","vul":"","ag":"Ganha: quem solicita e os gestores. Perde: setores ficam expostos por atrasos.","alt":"E se o processo tiver etapas desnecessárias?","esc":{"micro":"Etapa atual no topo do processo.","meso":"Fluxo visual com responsável e tempo parado.","macro":"Reorganizar o fluxo mostrando cada etapa com o responsável nomeado e o tempo parado."},"st":"add","sub":"Remover etapas de aprovação que não agregam.","ops":["U01","U15"],"c2":{"c":"C26","t":"Expor o tempo parado por setor pode gerar conflito entre equipes.","mit":"Usar os dados para redistribuir carga, não para punir."},"cf":"Sem intervenção, processos ficam parados e ninguém é responsabilizado.","lim":{"l":"L06","t":"Mudar o fluxo depende de normas internas."},"ide":{"mais":["I09"],"menos":["I06"]},"ref":"Estaria errada se os atrasos vierem de falta de pessoal, e não de falta de visibilidade.","conf":"média"},
{"id":42,"h":1,"sev":3,"t":"Erro dentro de seção recolhida","sym":"A declaração de imposto não envia porque há um erro numa seção fechada.","ten":"Recolher seções simplifica, mas esconde problemas.","sol":"Condicionar o recolhimento: seção com erro fica sempre aberta, com o título marcado.","c":"C08","u":"U21","e":"micro","i":"I04","m":"Envios travados sem motivo aparente","freq":2,"imp":2,"pers":2,"pf":"P01","hx":["BS5.1","BS1.4","DN1","ISO6","WC3.3"],"dom":"financas","vul":"","ag":"Ganha: quem declara. Perde: seções abertas deixam o formulário mais longo.","alt":"E se recolher seções não for necessário?","esc":{"micro":"Condicionar o recolhimento: seção com erro fica sempre aberta, com o título marcado.","meso":"Seções com contagem de pendências no título.","macro":"Validação ao final de cada seção."},"st":"sub","sub":"A própria solução é subtrativa: não recolher seções que tenham erros.","ops":["U01","U07"],"c2":{"c":"C17","t":"Seções abertas deixam o formulário mais longo.","mit":"Abrir só as que têm erro."},"cf":"Sem intervenção, a pessoa não consegue enviar e não sabe por quê.","lim":{"l":"L03","t":"Nenhum limite relevante."},"ide":{"mais":["I04"],"menos":["I03"]},"ref":"Estaria errada se o erro estiver em campo visível mas não percebido.","conf":"alta"},
{"id":43,"h":1,"sev":3,"t":"Mapa sem “você está aqui”","sym":"O mapa abre numa região qualquer, sem posição nem escala.","ten":"O mapa mostra o território, mas a pessoa precisa se situar nele.","sol":"Marcar a posição atual, mostrar escala e botão para recentralizar.","c":"C10","u":"U12","e":"micro","i":"I09","m":"Tempo para se orientar","freq":2,"imp":2,"pers":2,"pf":"P01","hx":["MB1","MB2","DN1","DN4","ISO2"],"dom":"mobilidade","vul":"","ag":"Ganha: quem se desloca. Perde: mostrar a posição exige acesso à localização.","alt":"E se a pessoa não quiser compartilhar a localização?","esc":{"micro":"Marcar a posição atual, mostrar escala e botão para recentralizar.","meso":"Pontos de referência visíveis (estações, praças).","macro":"Mapas integrados à sinalização física das estações."},"st":"add","sub":"Remover camadas de informação que escondem o essencial.","ops":["U01","U16"],"c2":{"c":"C05","t":"Mostrar a posição exige acesso à localização.","mit":"Explicar o uso e funcionar também sem ela."},"cf":"Sem intervenção, a pessoa perde tempo tentando se situar.","lim":{"l":"L02","t":"Precisão do GPS em áreas fechadas."},"ide":{"mais":["I09"],"menos":["I05"]},"ref":"Estaria errada se o problema for o mapa desatualizado.","conf":"alta"},
{"id":44,"h":1,"sev":3,"t":"Idioma trocado automaticamente","sym":"Numa viagem, o site passa a aparecer em outro idioma sem aviso.","ten":"Adaptar à região ajuda, mas a escolha deve ser de quem usa.","sol":"Nunca trocar sozinho: sugerir o idioma local e manter a preferência da pessoa.","c":"C21","u":"U14","e":"macro","i":"I07","m":"Trocas manuais de idioma","freq":2,"imp":2,"pers":2,"pf":"P14","hx":["TG2","BS3.1","ISO5","SH7","MB6"],"dom":"mobilidade","vul":"estrangeiros","ag":"Ganha: quem viaja. Perde: nada.","alt":"E se a mudança automática existir para atender turistas locais?","esc":{"micro":"Aviso com opção de manter o idioma.","meso":"Seletor de idioma sempre visível.","macro":"Nunca trocar sozinho: sugerir o idioma local e manter a preferência da pessoa."},"st":"sub","sub":"A própria solução é subtrativa: remove a troca automática de idioma.","ops":["U01","U36"],"c2":{"c":"C21","t":"Turistas que queriam o idioma local precisam trocá-lo à mão.","mit":"Sugerir a troca, sem impor."},"cf":"Sem intervenção, as pessoas usam o app em um idioma que não entendem.","lim":{"l":"L03","t":"Nenhum limite relevante."},"ide":{"mais":["I07"],"menos":[]},"ref":"Estaria errada se a troca for pedida pela própria pessoa.","conf":"média"},
{"id":45,"h":1,"sev":2,"t":"Resultados sem total","sym":"A busca de passagens mostra voos, mas não quantos existem.","ten":"Mostrar tudo seria pesado, mas o tamanho do conjunto orienta a busca.","sol":"Exibir “1–20 de 347 resultados” e atualizar ao filtrar.","c":"C13","u":"U01","e":"micro","i":"I09","m":"Refinamentos de busca","freq":2,"imp":1,"pers":2,"pf":"P01","hx":["GP2","BS1.4","ISO2","LX2"],"dom":"mobilidade","vul":"","ag":"Ganha: quem compara passagens. Perde: nada.","alt":"E se o total for enganoso por incluir voos indisponíveis?","esc":{"micro":"Exibir “1–20 de 347 resultados” e atualizar ao filtrar.","meso":"Resumo por faixa de preço e horário.","macro":"Integração com companhias para dados reais."},"st":"add","sub":"Remover resultados indisponíveis da contagem.","ops":["U35","U08"],"c2":{"c":"C17","t":"Números grandes podem desanimar.","mit":"Sugerir filtros junto do total."},"cf":"Sem intervenção, a pessoa não sabe se viu todas as opções.","lim":{"l":"L03","t":"Nenhum limite relevante."},"ide":{"mais":["I09"],"menos":[]},"ref":"Estaria errada se, em teste, quem vê o total e quem não vê escolher voos igualmente bons no mesmo tempo.","conf":"média"},
{"id":46,"h":1,"sev":3,"t":"Vídeo publicado aparece indisponível","sym":"A videoaula enviada pela professora aparece “indisponível” sem explicação.","ten":"O processamento leva minutos, mas a pessoa acha que falhou.","sol":"Mostrar “Processando — cerca de 5 min”, com aviso quando estiver pronto.","c":"C15","u":"U19","e":"meso","i":"I09","m":"Reenvios do mesmo vídeo","freq":2,"imp":2,"pers":2,"pf":"P06","hx":["SH3","GP2","BS1.4","ISO2","TG10"],"dom":"educacao","vul":"","ag":"Ganha: professores. Perde: nada.","alt":"E se o processamento puder ser mais rápido?","esc":{"micro":"Mensagem “Processando — cerca de 5 min”.","meso":"Mostrar “Processando — cerca de 5 min”, com aviso quando estiver pronto.","macro":"Processamento mais rápido no servidor."},"st":"add","sub":"Remover o processamento: publicar o vídeo original e converter depois.","ops":["U20","U08"],"c2":{"c":"C27","t":"Previsão de tempo errada gera desconfiança.","mit":"Mostrar faixa de tempo."},"cf":"Sem intervenção, professores reenviam o mesmo vídeo várias vezes.","lim":{"l":"L03","t":"Depende da infraestrutura."},"ide":{"mais":["I09"],"menos":[]},"ref":"Estaria errada se os reenvios forem por erro no arquivo.","conf":"alta"},
{"id":47,"h":1,"sev":3,"t":"Senha sem indicador de força","sym":"A pessoa cria “123456” sem saber que é fraca.","ten":"A senha deve ser fácil de lembrar, mas difícil de adivinhar.","sol":"Medidor de força em tempo real com dica concreta de como melhorar.","c":"C25","u":"U32","e":"micro","i":"I05","m":"Senhas fracas cadastradas","freq":3,"imp":2,"pers":2,"pf":"P03","hx":["BS1.4","GP4","SH3","ISO4","TG11"],"dom":"financas","vul":"","ag":"Ganha: clientes. Perde: medidores muito exigentes levam a senhas difíceis de lembrar.","alt":"E se a senha em si não for necessária (biometria, chave de acesso)?","esc":{"micro":"Medidor de força em tempo real com dica concreta de como melhorar.","meso":"Opção de chave de acesso (passkey) no cadastro.","macro":"Autenticação sem senha como padrão."},"st":"add","sub":"Remover regras de senha que não aumentam a segurança real.","ops":["U19","U16"],"c2":{"c":"C23","t":"Medidores muito exigentes levam a senhas difíceis de lembrar.","mit":"Aceitar frases longas e simples."},"cf":"Sem intervenção, senhas fracas são cadastradas.","lim":{"l":"L07","t":"Pessoas têm dificuldade de lembrar senhas complexas."},"ide":{"mais":["I05"],"menos":["I03"]},"ref":"Estaria errada se as pessoas já usarem gerenciador de senhas.","conf":"alta"},
{"id":48,"h":1,"sev":3,"t":"Reembolso invisível","sym":"A passagem foi cancelada e ninguém sabe se o dinheiro voltou.","ten":"O estorno depende do banco, mas o cliente precisa acompanhar.","sol":"Linha do tempo do reembolso com prazo por meio de pagamento e compromisso público de prazo, com compensação se atrasar.","c":"C33","u":"U01","e":"macro","i":"I06","m":"Contatos sobre reembolso","freq":2,"imp":2,"pers":3,"pf":"P08","hx":["SH3","GP2","ISO2","BS1.4"],"dom":"mobilidade","vul":"","ag":"Ganha: o viajante. Perde: a empresa precisa cumprir prazos públicos.","alt":"E se o reembolso fosse automático e imediato em crédito?","esc":{"micro":"Etiqueta de status do reembolso no pedido, com a data prevista.","meso":"Linha do tempo do reembolso com prazo por meio de pagamento.","macro":"Linha do tempo do reembolso com prazo por meio de pagamento e compromisso público de prazo, com compensação se atrasar."},"st":"add","sub":"Remover a necessidade de pedir reembolso: devolver automaticamente em cancelamentos da empresa.","ops":["U15","U19"],"c2":{"c":"C26","t":"Reembolso automático custa caixa à empresa.","mit":"Oferecer crédito com bônus como alternativa opcional."},"cf":"Sem intervenção, clientes ligam e registram reclamações.","lim":{"l":"L06","t":"Prazos de reembolso são regulados."},"ide":{"mais":["I06"],"menos":["I02"]},"ref":"Estaria errada se os contatos forem sobre o valor, e não sobre o status.","conf":"alta"},
{"id":49,"h":1,"sev":3,"t":"Automação age sem deixar rastro","sym":"O assistente de IA move e-mails para pastas “sozinho” e ninguém sabe por quê.","ten":"As regras automáticas economizam trabalho, mas precisam ser rastreáveis.","sol":"Registro de atividade: “Movido pela regra X às 10:02”, com link para a regra.","c":"C27","u":"U36","e":"meso","i":"I09","m":"Dúvidas sobre mudanças misteriosas","freq":2,"imp":2,"pers":2,"pf":"P11","hx":["IA11","IA16","GP2","ISO2","TG15"],"dom":"ia","vul":"","ag":"Ganha: quem usa as automações. Perde: registros detalhados poluem o histórico.","alt":"E se as regras forem complexas demais para entender?","esc":{"micro":"Selo “movido por regra” na mensagem.","meso":"Registro de atividade: “Movido pela regra X às 10:02”, com link para a regra.","macro":"Painel de regras com teste antes de ativar."},"st":"add","sub":"Remover regras antigas não usadas.","ops":["U01","U25"],"c2":{"c":"C17","t":"Registros detalhados poluem o histórico.","mit":"Resumo com opção de ver detalhes."},"cf":"Sem intervenção, as pessoas desconfiam do sistema e desligam as automações.","lim":{"l":"L03","t":"Nenhum limite relevante."},"ide":{"mais":["I09"],"menos":["I03"]},"ref":"Estaria errada se as mudanças forem feitas por outras pessoas.","conf":"média"},
{"id":50,"h":1,"sev":4,"t":"Gravação pública sem que se saiba","sym":"Gravações da câmera de segurança compartilhadas “com o link” estão acessíveis a qualquer pessoa.","ten":"Compartilhar deve ser fácil, mas o alcance precisa ser evidente.","sol":"Selo de visibilidade (Privado, Equipe, Público) sempre visível junto ao nome do arquivo.","c":"C03","u":"U01","e":"meso","i":"I05","m":"Documentos expostos sem intenção","freq":2,"imp":3,"pers":2,"pf":"P13","hx":["DN1","SH7","ISO5","TG5","MB7"],"dom":"casa","vul":"","ag":"Ganha: a privacidade da família. Perde: selos em todos os arquivos poluem a lista.","alt":"E se o link público não precisar existir?","esc":{"micro":"Selo de visibilidade no arquivo.","meso":"Selo de visibilidade (Privado, Equipe, Público) sempre visível junto ao nome do arquivo.","macro":"Links públicos expiram automaticamente."},"st":"mod","sub":"Remover o link público como padrão.","ops":["U21","U20"],"c2":{"c":"C17","t":"Selos em todos os arquivos poluem a lista.","mit":"Destacar só os públicos."},"cf":"Sem intervenção, gravações da casa ficam expostas.","lim":{"l":"L06","t":"Leis de proteção de dados."},"ide":{"mais":["I05"],"menos":["I02"]},"ref":"Estaria errada se as pessoas quiserem compartilhar publicamente.","conf":"alta"}
);
